body.script:
var sketch = {"visualID":2723192,"title":"Box Randomizer","slug":null,"isPjs":2,"description":"","instructions":"","tags":[],"license":"by-nc-sa","active":1,"isDraft":0,"isPrivate":0,"hideSourceCode":0,"createdOn":"2025-09-15 09:17:11","updatedOn":"2026-05-01 18:39:18","pinnedOn":null,"filesUpdatedOn":null,"thumbnailUpdatedOn":"2025-09-15 09:17:12","videoUpdatedOn":null,"deletedOn":null,"parentID":null,"engineID":2335,"isTutorial":0,"hasTimeline":0,"hasFrameBorder":true,"loopProtect":1,"commentMode":1,"ipfsHash":null,"libraries":[],"templateID":null,"isTemplate":0,"forkCount":0,"userID":447540,"showInstructions":true,"showFullscreen":false,"parentSketch":null,"username":"u447540","classes":[],"versions":[{"visualID":2723192,"versionID":17291472,"createdOn":"2025-10-22 14:20:37","updatedOn":"2025-10-22 14:20:37","archivedOn":null,"isArchived":0,"codeObjects":[{"codeID":40134178,"visualID":2723192,"orderID":0,"code":"/**
 * A4 Typesetter — sharp + SVG + Typeface dropdown
 * OpenProcessing / p5.js
 *
 * - A4 canvas (595 x 842), margin = 25px (layout only); paper fills entire canvas
 * - Background behind paper is independent (default #000000)
 * - Alignments: Left / Center / Right
 * - Per-word box fill + per-word text color (click a word to select)
 * - Boxes touch with no gaps; paragraph spacing after manual newline
 * - Sliders: font size, letter spacing (-5..30 px), paragraph spacing
 * - Toggle: box outline on/off
 *
 * Randomizers:
 * - #1 Colors: palette-based; Randomize once / Play-Pause + Speed
 * - #2 Words+Colors: shuffles the base sentence + Palette 1 colors
 * - #3 Glitch (SPACERS ONLY): inserts EMPTY COLORED BOXES *between words* (Palette 1)
 *
 * New:
 * - **Typeface dropdown (3 options)** — Typeface 1 is the original `sans-serif`
 * - **Sharper rendering** — device pixel density + smoothing disabled
 * - **Export** — Copy SVG / Download SVG (uses chosen typeface)
 */

const A4_W = 595;
const A4_H = 842;
const MARGIN = 25;
const PAPER_RADIUS = 0;
const BOX_PAD = 0;
const SIDE_EXTEND = 0; // exact tiling

// ---- Base sentence (for Randomizer #2) ----
const BASE_SENTENCE = `Life is the journey of the One expressed through the many, each fragment returning toward its source in unity.`;

// ---- Palettes ----
const palettes = {
 palette1: {
 label: 'Color palette 1',
 boxChoices: ['#6DC1E8', '#5FB946', '#FB1F8D', '#101010'],
 textForBox: (hex) => (hex.toUpperCase() === '#101010' ? '#FFFFFF' : '#101010'),
 paper: '#FFD23A',
 background: '#000000',
 },
 palette2: {
 label: 'Color palette 2 — B/W',
 boxChoices: ['#000000', '#FFFFFF'],
 textForBox: (hex) => (hex.toUpperCase() === '#000000' ? '#FFFFFF' : '#000000'),
 paper: '#FFFFFF',
 background: '#FF0088', // reference only
 },
 palette3: {
 label: 'Color palette 3 — Sunset',
 boxChoices: ['#FF6B6B', '#FFD93D', '#6BCB77', '#1B1B1E'],
 textForBox: (hex) => autoTextFor(hex),
 paper: '#FFF8E7',
 background: '#1A1A1A',
 },
 palette4: {
 label: 'Color palette 4 — Cyber',
 boxChoices: ['#00E5FF', '#7C4DFF', '#FFEA00', '#121212'],
 textForBox: (hex) => autoTextFor(hex),
 paper: '#0E0E10',
 background: '#000000',
 }
};
let currentPaletteKey = 'palette1';

// ---------- UI ----------
let ui;
let bgPicker, paperPicker, textDefaultPicker;
let sizeSlider, letterSlider, paraSlider;
let sizeVal = null, letterVal = null, paraVal = null;
let fontSelect, currentFont = 'sans-serif'; // Typeface 1 (original)
let textArea, selectedLabel = null;
let selBoxFillPicker, selTextColorPicker;
let outlineToggle;
let alignmentSelect;

// Randomizer #1 UI/state
let paletteSelect, randomizeBtn, playBtn, speedSlider, speedVal;
let isPlaying = false;
let lastRandomizeAt = 0;

// Randomizer #2 UI
let randomizeWordsBtn;

// Randomizer #3 (Glitch Spaces) UI/state
let glitchChaosSlider, glitchChaosVal, glitchPlayBtn, glitchOnceBtn, glitchSpeedSlider, glitchSpeedVal;
let isPlayingGlitch = false;
let lastGlitchAt = 0;
let glitchActive = false;
let lastGlitchChaos = 0.6;

// Export UI
let copySVGBtn, downloadSVGBtn;

// ---------- Data ----------
let paragraph = BASE_SENTENCE;

// Word layout for normal rendering & selection
let wordRects = []; // [{word,xGlyph,y,rectX,rectW,ascent,descent,letterSpacing,boxFillColor,textColor}]

// Glitch rendering list (words + spacer boxes). Built fresh each glitch step.
let glitchRects = []; // [{type:'word'|'spacer', x, y, w, h, ascent, descent, wordIndex?, text?, boxFill?, textFill?}]

let selectedIndex = -1;
let dirtyLayout = true;
let glitchLayoutDirty = false;

// canvas reference (for crisp CSS hint)
let cnv;

function setup() {
 cnv = createCanvas(A4_W, A4_H);

 // --- SHARP RENDERING ---
 const d = max(1, round(displayDensity()));
 pixelDensity(d);
 drawingContext.imageSmoothingEnabled = false;
 try { cnv.style('image-rendering', 'pixelated'); } catch(e){}

 textFont(currentFont);
 textAlign(LEFT, BASELINE);

 buildUI();
 layoutWords();
}

function draw() {
 drawingContext.imageSmoothingEnabled = false;

 // Background behind paper (NOT changed by randomizers)
 background(bgPicker.value());

 // Paper fills the canvas
 noStroke();
 fill(paperPicker.value());
 rect(0, 0, width, height, PAPER_RADIUS);

 if (dirtyLayout) { layoutWords(); dirtyLayout = false; glitchLayoutDirty = true; }

 // Auto Randomizer #1 (colors)
 if (isPlaying) {
 const perSecond = max(0.1, speedSlider.value());
 const intervalMs = 1000 / perSecond;
 if (millis() - lastRandomizeAt >= intervalMs) {
 applyRandomizer();
 lastRandomizeAt = millis();
 }
 }

 // Auto Randomizer #3 (glitch spaces)
 if (isPlayingGlitch) {
 const perSecond = max(0.1, glitchSpeedSlider.value());
 const intervalMs = 1000 / perSecond;
 if (millis() - lastGlitchAt >= intervalMs) {
 applyGlitchSpaces(lastGlitchChaos);
 lastGlitchAt = millis();
 }
 }

 // Build glitch layout if needed
 if (glitchActive && glitchLayoutDirty) {
 buildGlitchRects(lastGlitchChaos);
 glitchLayoutDirty = false;
 }

 // ---- Draw ----
 if (glitchActive) {
 if (outlineToggle && outlineToggle.checked()) { stroke(0); strokeWeight(1); }
 else { noStroke(); }

 for (const r of glitchRects) {
 if (r.boxFill) fill(r.boxFill); else noFill();
 rect(r.x, r.y - r.ascent - BOX_PAD, r.w, r.ascent + r.descent + BOX_PAD * 2);
 }

 noStroke();
 for (const r of glitchRects) {
 if (r.type === 'word' && r.text) {
 fill(r.textFill || textDefaultPicker.value());
 drawWordWithLetterSpacing(r.text, r.x, r.y, letterSlider.value());
 }
 }
 } else {
 if (outlineToggle && outlineToggle.checked()) { stroke(0); strokeWeight(1); }
 else { noStroke(); }

 for (const wr of wordRects) {
 if (wr.boxFillColor) fill(wr.boxFillColor); else noFill();
 rect(wr.rectX, wr.y - wr.ascent - BOX_PAD, wr.rectW, wr.ascent + wr.descent + BOX_PAD * 2);
 }

 noStroke();
 for (const wr of wordRects) {
 const tcol = wr.textColor ? wr.textColor : textDefaultPicker.value();
 fill(tcol);
 drawWordWithLetterSpacing(wr.word, wr.xGlyph, wr.y, wr.letterSpacing);
 }
 }

 // UI readouts
 const fmt = (v, dp=0) => (typeof nf === 'function' ? nf(v, 1, dp) : Number(v).toFixed(dp));
 if (sizeVal) sizeVal.html(fmt(sizeSlider.value(), 0) + ' px');
 if (letterVal) letterVal.html(fmt(letterSlider.value(), 1) + ' px');
 if (paraVal) paraVal.html(fmt(paraSlider.value(), 0) + ' px');
 if (speedVal) speedVal.html(fmt(speedSlider.value(), 1) + ' /s');
 if (glitchChaosVal) glitchChaosVal.html(fmt(glitchChaosSlider.value(), 2));
 if (glitchSpeedVal) glitchSpeedVal.html(fmt(glitchSpeedSlider.value(), 1) + ' /s');

 if (selectedLabel) {
 if (selectedIndex >= 0 && selectedIndex < wordRects.length) {
 selectedLabel.html('Selected word: <b>' + sanitize(wordRects[selectedIndex].word) + '</b>');
 } else {
 selectedLabel.html('Selected word: <i>none</i>');
 }
 }
}

// ---------------- UI ----------------

function buildUI() {
 ui = createDiv();
 ui.style('position', 'fixed');
 ui.style('top', '12px');
 ui.style('right', '12px');
 ui.style('max-width', '460px');
 ui.style('padding', '12px');
 ui.style('background', '#ffffff');
 ui.style('border', '1px solid #ddd');
 ui.style('border-radius', '10px');
 ui.style('box-shadow', '0 4px 16px rgba(0,0,0,0.08)');
 ui.style('font', '13px/1.4 system-ui, -apple-system, Segoe UI, Roboto, Arial');

 // Canvas Colors
 addSectionTitle(ui, 'Canvas Colors');
 addLabel(ui, 'Background (behind paper — unaffected by randomizers)');
 bgPicker = createColorPicker('#000000'); bgPicker.parent(ui); addGap(ui);

 addLabel(ui, 'Canvas / Paper color (fills full canvas)');
 paperPicker = createColorPicker('#ffffff'); paperPicker.parent(ui);

 // Typography
 addSectionTitle(ui, 'Typography');

 const faceRow = createDiv(); faceRow.parent(ui); stylizeRow(faceRow);
 addLabel(faceRow, 'Typeface');
 fontSelect = createSelect(); fontSelect.parent(faceRow);
 fontSelect.option('Typeface 1 — Original (sans-serif)', 'sans-serif');
 fontSelect.option('Typeface 2 — Serif', 'serif');
 fontSelect.option('Typeface 3 — Mono', 'monospace');
 fontSelect.value('sans-serif');

 const sizeRow = createDiv(); sizeRow.parent(ui); stylizeRow(sizeRow);
 addLabel(sizeRow, 'Font size');
 sizeSlider = createSlider(8, 120, 28, 1); sizeSlider.parent(sizeRow);
 sizeVal = createSpan(''); sizeVal.parent(sizeRow);

 const letterRow = createDiv(); letterRow.parent(ui); stylizeRow(letterRow);
 addLabel(letterRow, 'Letter spacing');
 letterSlider = createSlider(-5, 30, 0, 0.5); letterSlider.parent(letterRow);
 letterVal = createSpan(''); letterVal.parent(letterRow);

 const paraRow = createDiv(); paraRow.parent(ui); stylizeRow(paraRow);
 addLabel(paraRow, 'Paragraph spacing (after newline)');
 paraSlider = createSlider(0, 120, 0, 1); paraSlider.parent(paraRow);
 paraVal = createSpan(''); paraVal.parent(paraRow);

 // Alignment
 addSectionTitle(ui, 'Alignment');
 const alignRow = createDiv(); alignRow.parent(ui); stylizeRow(alignRow);
 addLabel(alignRow, 'Text alignment');
 alignmentSelect = createSelect(); alignmentSelect.parent(alignRow);
 alignmentSelect.option('Left', 'left');
 alignmentSelect.option('Center', 'center');
 alignmentSelect.option('Right', 'right');
 alignmentSelect.value('left');

 // Text Content
 addSectionTitle(ui, 'Text Content');
 addLabel(ui, 'Paragraph (use Enter for line breaks)');
 textArea = createElement('textarea');
 textArea.attribute('rows', 5);
 textArea.style('width', '100%');
 textArea.style('box-sizing', 'border-box');
 textArea.value(paragraph);
 textArea.parent(ui);

 // Boxes & Selection
 addSectionTitle(ui, 'Boxes & Selection');
 outlineToggle = createCheckbox('Show box outline', true); outlineToggle.parent(ui);
 addLabel(ui, 'Default text color (used when a word has no override)');
 textDefaultPicker = createColorPicker('#111111'); textDefaultPicker.parent(ui);

 addLabel(ui, 'Selected box fill');
 selBoxFillPicker = createColorPicker('#ff0055'); selBoxFillPicker.parent(ui);

 addLabel(ui, 'Selected text color');
 selTextColorPicker = createColorPicker('#0055ff'); selTextColorPicker.parent(ui);

 selectedLabel = createDiv('Selected word: <i>none</i>');
 selectedLabel.parent(ui);
 selectedLabel.style('margin', '6px 0 0 0');

 // Randomizer #1 — Colors
 addSectionTitle(ui, 'Randomizer #1 — Colors');
 const palRow = createDiv(); palRow.parent(ui); stylizeRow(palRow);
 addLabel(palRow, 'Palette');
 paletteSelect = createSelect(); paletteSelect.parent(palRow);
 for (const key in palettes) paletteSelect.option(palettes[key].label, key);
 paletteSelect.value(currentPaletteKey);

 const rndRow = createDiv(); rndRow.parent(ui); stylizeRow(rndRow);
 randomizeBtn = createButton('Randomize once'); randomizeBtn.parent(rndRow);
 playBtn = createButton('▶ Play'); playBtn.parent(rndRow);

 const speedRow = createDiv(); speedRow.parent(ui); stylizeRow(speedRow);
 addLabel(speedRow, 'Speed');
 speedSlider = createSlider(0.2, 10, 2, 0.1); speedSlider.parent(speedRow);
 speedVal = createSpan(''); speedVal.parent(speedRow);

 // Randomizer #2 — Words + Colors
 addSectionTitle(ui, 'Randomizer #2 — Words + Colors (Palette 1 rules)');
 randomizeWordsBtn = createButton('Randomize words + colors'); randomizeWordsBtn.parent(ui);
 randomizeWordsBtn.style('margin-top', '6px');

 // Randomizer #3 — Glitch Spaces
 addSectionTitle(ui, 'Randomizer #3 — Glitch (empty colored boxes between words)');
 const chaosRow = createDiv(); chaosRow.parent(ui); stylizeRow(chaosRow);
 addLabel(chaosRow, 'Chaos (box density)');
 glitchChaosSlider = createSlider(0, 1, lastGlitchChaos, 0.01); glitchChaosSlider.parent(chaosRow);
 glitchChaosVal = createSpan(''); glitchChaosVal.parent(chaosRow);

 const gBtnRow = createDiv(); gBtnRow.parent(ui); stylizeRow(gBtnRow);
 glitchOnceBtn = createButton('Glitch once'); glitchOnceBtn.parent(gBtnRow);
 glitchPlayBtn = createButton('▶ Play'); glitchPlayBtn.parent(gBtnRow);

 const gSpeedRow = createDiv(); gSpeedRow.parent(ui); stylizeRow(gSpeedRow);
 addLabel(gSpeedRow, 'Glitch speed');
 glitchSpeedSlider = createSlider(0.2, 20, 4, 0.1); glitchSpeedSlider.parent(gSpeedRow);
 glitchSpeedVal = createSpan(''); glitchSpeedVal.parent(gSpeedRow);

 // Export
 addSectionTitle(ui, 'Export');
 const exportRow = createDiv(); exportRow.parent(ui); stylizeButtonsRow(exportRow);
 copySVGBtn = createButton('Copy SVG'); copySVGBtn.parent(exportRow);
 downloadSVGBtn = createButton('Download SVG'); downloadSVGBtn.parent(exportRow);

 // Actions
 const btnRow = createDiv(); btnRow.parent(ui); stylizeButtonsRow(btnRow);
 const clearSel = createButton('Clear selection'); clearSel.parent(btnRow);
 const resetAll = createButton('Reset all overrides'); resetAll.parent(btnRow);

 // Events
 const markDirty = () => { dirtyLayout = true; glitchLayoutDirty = true; };
 textArea.input(() => { paragraph = textArea.value(); markDirty(); });
 sizeSlider.input(markDirty);
 letterSlider.input(markDirty);
 paraSlider.input(markDirty);
 alignmentSelect.changed(markDirty);
 paletteSelect.changed(() => { currentPaletteKey = paletteSelect.value(); });
 fontSelect.changed(() => {
 currentFont = fontSelect.value();
 textFont(currentFont);
 dirtyLayout = true;
 glitchLayoutDirty = true;
 });

 selBoxFillPicker.input(() => {
 if (selectedIndex >= 0 && selectedIndex < wordRects.length) {
 wordRects[selectedIndex].boxFillColor = selBoxFillPicker.value();
 }
 });

 selTextColorPicker.input(() => {
 if (selectedIndex >= 0 && selectedIndex < wordRects.length) {
 wordRects[selectedIndex].textColor = selTextColorPicker.value();
 }
 });

 randomizeBtn.mousePressed(() => { applyRandomizer(); lastRandomizeAt = millis(); });
 playBtn.mousePressed(() => {
 isPlaying = !isPlaying;
 playBtn.html(isPlaying ? '⏸ Pause' : '▶ Play');
 lastRandomizeAt = millis();
 });

 randomizeWordsBtn.mousePressed(() => { applyWordShuffleAndColors(); });

 glitchOnceBtn.mousePressed(() => {
 lastGlitchChaos = glitchChaosSlider.value();
 applyGlitchSpaces(lastGlitchChaos);
 });
 glitchPlayBtn.mousePressed(() => {
 isPlayingGlitch = !isPlayingGlitch;
 glitchPlayBtn.html(isPlayingGlitch ? '⏸ Pause' : '▶ Play');
 lastGlitchChaos = glitchChaosSlider.value();
 lastGlitchAt = millis();
 glitchActive = true;
 });

 copySVGBtn.mousePressed(copySVGToClipboard);
 downloadSVGBtn.mousePressed(downloadSVGFile);

 clearSel.mousePressed(() => { selectedIndex = -1; });

 resetAll.mousePressed(() => {
 for (let wr of wordRects) { wr.boxFillColor = null; wr.textColor = null; }
 glitchActive = false;
 glitchRects = [];
 });
}

function addSectionTitle(parent, txt) {
 const t = createElement('div', txt);
 t.parent(parent);
 t.style('margin', '12px 0 6px 0');
 t.style('font-weight', '700');
 t.style('opacity', '0.9');
 return t;
}

function stylizeRow(row) {
 row.style('display', 'flex');
 row.style('gap', '8px');
 row.style('align-items', 'center');
 row.style('margin-top', '6px');
 row.style('flex-wrap', 'wrap');
}

function stylizeButtonsRow(row) {
 row.style('display', 'flex');
 row.style('gap', '8px');
 row.style('margin-top', '10px');
 row.style('flex-wrap', 'wrap');
}

function addLabel(parent, txt) {
 const lbl = createElement('div', txt);
 lbl.parent(parent);
 lbl.style('opacity', '0.8');
 lbl.style('margin', '2px 0');
 return lbl;
}

function addGap(parent) {
 const gap = createDiv('');
 gap.parent(parent);
 gap.style('height', '8px');
}

// ---------------- Normal layout (non-glitch) ----------------

function layoutWords() {
 // Preserve per-word overrides by index
 const old = wordRects.map(w => ({ boxFillColor: w.boxFillColor, textColor: w.textColor }));

 wordRects = [];

 const fontSize = sizeSlider.value();
 const letterSpacing = letterSlider.value();
 const paraSpacing = paraSlider.value();
 const align = alignmentSelect ? alignmentSelect.value() : 'left';

 textFont(currentFont);
 textSize(fontSize);
 textStyle(NORMAL);
 textAlign(LEFT, BASELINE);

 const ascent = textAscent();
 const descent = textDescent();
 const lineHeight = ascent + descent;

 const xStart = MARGIN + BOX_PAD;
 const yStart = MARGIN + BOX_PAD + ascent;
 const xMax = width - MARGIN - BOX_PAD;
 const yMax = height - MARGIN - BOX_PAD;
 const lineAreaWidth = xMax - xStart;

 const raw = paragraph.replace(/\r/g, '');
 const lines = raw.split('\n');

 let y = yStart;
 let idx = 0;
 const spaceW = textWidth(' ') + letterSpacing;

 for (let li = 0; li < lines.length; li++) {
 const lineText = lines[li];

 if (!lineText.trim().length) {
 y += lineHeight;
 if (li < lines.length - 1) y += paraSpacing;
 if (y + descent + BOX_PAD > yMax) break;
 continue;
 }

 const words = lineText.trim().split(/\s+/);

 // wrap into visual lines (normal spacing)
 const vLines = [];
 let cur = [];
 let wAccum = 0;

 for (let wj = 0; wj < words.length; wj++) {
 const w = words[wj];
 const ww = measureWordWithLS(w, letterSpacing);
 const projected = cur.length === 0 ? ww : (wAccum + spaceW + ww);
 if (projected > lineAreaWidth && cur.length > 0) {
 vLines.push({ items: cur, width: wAccum });
 cur = [{ w, ww }];
 wAccum = ww;
 } else {
 if (cur.length === 0) { cur.push({ w, ww }); wAccum = ww; }
 else { cur.push({ w, ww }); wAccum += spaceW + ww; }
 }
 }
 if (cur.length) vLines.push({ items: cur, width: wAccum });

 // place each visual line with symmetric halves so word boxes touch
 for (const vline of vLines) {
 let x = xStart;
 if (align === 'center') x += (lineAreaWidth - vline.width) / 2;
 else if (align === 'right') x += (lineAreaWidth - vline.width);

 for (let j = 0; j < vline.items.length; j++) {
 const item = vline.items[j];
 const ww = item.ww;
 const leftHalf = (j === 0) ? 0 : spaceW / 2;
 const rightHalf = (j === vline.items.length - 1) ? 0 : spaceW / 2;

 const rectX = x - leftHalf - SIDE_EXTEND;
 const rectW = ww + leftHalf + rightHalf + SIDE_EXTEND * 2;

 wordRects.push({
 word: item.w,
 xGlyph: x,
 y: y,
 rectX,
 rectW,
 ascent,
 descent,
 letterSpacing,
 boxFillColor: old[idx]?.boxFillColor ?? null,
 textColor: old[idx]?.textColor ?? null
 });
 idx++;

 x += ww;
 if (j < vline.items.length - 1) x += spaceW;
 }

 y += lineHeight;
 if (y + descent + BOX_PAD > yMax) break;
 }

 if (li < lines.length - 1) {
 y += paraSpacing;
 if (y + descent + BOX_PAD > yMax) break;
 }
 }
}

// ---------------- Glitch Spaces (words + spacer boxes) ----------------

function applyGlitchSpaces(chaos) {
 glitchActive = true;
 lastGlitchChaos = chaos;
 buildGlitchRects(chaos);
 glitchLayoutDirty = false;
}

function buildGlitchRects(chaos) {
 glitchRects = [];

 const fontSize = sizeSlider.value();
 const letterSpacing = letterSlider.value();
 const paraSpacing = paraSlider.value();
 const align = alignmentSelect ? alignmentSelect.value() : 'left';

 textFont(currentFont);
 textSize(fontSize);
 textStyle(NORMAL);
 textAlign(LEFT, BASELINE);

 const ascent = textAscent();
 const descent = textDescent();
 const lineHeight = ascent + descent;

 const xStart = MARGIN + BOX_PAD;
 const yStart = MARGIN + BOX_PAD + ascent;
 const xMax = width - MARGIN - BOX_PAD;
 const yMax = height - MARGIN - BOX_PAD;
 const lineAreaWidth = xMax - xStart;

 const pal = palettes.palette1; // always palette 1 for spacers
 const raw = paragraph.replace(/\r/g, '');
 const lines = raw.split('\n');

 let y = yStart;
 let idx = 0; // index into wordRects (for colors/selection)

 // Controls for spacer density/widths
 const KMAX = 8; // potential spacers per boundary
 const spaceBase = textWidth(' ') + letterSpacing;
 const minSpacer = max(2, spaceBase * 0.15);
 const maxSpacer = max(minSpacer + 1, spaceBase * (0.5 + 3.5 * chaos));

 for (let li = 0; li < lines.length; li++) {
 const lineText = lines[li];

 if (!lineText.trim().length) {
 y += lineHeight;
 if (li < lines.length - 1) y += paraSpacing;
 if (y + descent + BOX_PAD > yMax) break;
 continue;
 }

 const words = lineText.trim().split(/\s+/);

 // Build a flat item list for this textual line: word, [spacers], word, [spacers], ...
 const items = [];
 for (let wj = 0; wj < words.length; wj++) {
 const w = words[wj];
 const ww = measureWordWithLS(w, letterSpacing);

 // WORD item
 items.push({ type: 'word', width: ww, word: w, wordIndex: idx });

 // Spacers after this word (incl. end with reduced probability)
 const kMean = chaos * KMAX;
 let K = floor(random(0, kMean + 1)); // ~0 .. KMAX*chaos
 if (wj === words.length - 1) K = floor(K * 0.5);
 for (let s = 0; s < K; s++) {
 const sw = random(minSpacer, maxSpacer);
 items.push({ type: 'spacer', width: sw, color: random(pal.boxChoices) });
 }

 idx++;
 }

 // Wrap items into visual lines by total width
 let lineItems = [];
 let acc = 0;
 const linesPacked = [];

 for (const it of items) {
 if (lineItems.length > 0 && acc + it.width > lineAreaWidth) {
 linesPacked.push({ items: lineItems, width: acc });
 lineItems = [it];
 acc = it.width;
 } else {
 lineItems.push(it);
 acc += it.width;
 }
 }
 if (lineItems.length) linesPacked.push({ items: lineItems, width: acc });

 // Place each packed line with alignment
 for (const L of linesPacked) {
 let x = xStart;
 if (align === 'center') x += (lineAreaWidth - L.width) / 2;
 else if (align === 'right') x += (lineAreaWidth - L.width);

 for (const it of L.items) {
 if (it.type === 'word') {
 const base = wordRects[it.wordIndex] || {};
 const boxFill = base.boxFillColor ?? null;
 const textFill = base.textColor ?? textDefaultPicker.value();

 glitchRects.push({
 type: 'word',
 x: x,
 y: y,
 w: it.width,
 ascent,
 descent,
 boxFill,
 textFill,
 text: it.word,
 wordIndex: it.wordIndex
 });
 } else {
 glitchRects.push({
 type: 'spacer',
 x: x,
 y: y,
 w: it.width,
 ascent,
 descent,
 boxFill: it.color,
 text: ''
 });
 }
 x += it.width; // boxes butt together (no gaps)
 }

 y += lineHeight;
 if (y + descent + BOX_PAD > yMax) break;
 }

 if (li < lines.length - 1) {
 y += paraSpacing; // only paragraph spacing adds vertical gap
 if (y + descent + BOX_PAD > yMax) break;
 }
 }
}

// ---------------- Helpers ----------------

function measureWordWithLS(word, letterSpacing) {
 if (!word || word.length === 0) return 0;
 textFont(currentFont);
 textSize(sizeSlider.value());
 let acc = 0;
 for (let i = 0; i < word.length; i++) {
 acc += textWidth(word[i]);
 if (i < word.length - 1) acc += letterSpacing;
 }
 return acc;
}

function drawWordWithLetterSpacing(word, x, y, letterSpacing) {
 textFont(currentFont);
 textSize(sizeSlider.value());
 let cx = x;
 for (let i = 0; i < word.length; i++) {
 text(word[i], cx, y);
 cx += textWidth(word[i]) + letterSpacing;
 }
}

function autoTextFor(hex) {
 const L = relLuminance(hexToRgb(hex));
 return L > 0.6 ? '#101010' : '#FFFFFF';
}

function hexToRgb(hex) {
 const h = hex.replace('#','');
 const bigint = parseInt(h.length === 3 ? h.split('').map(c=>c+c).join('') : h, 16);
 return { r:(bigint>>16)&255, g:(bigint>>8)&255, b:(bigint)&255 };
}

function relLuminance({r,g,b}) {
 const srgb = [r,g,b].map(v => v/255);
 const lin = srgb.map(c => (c <= 0.03928) ? c/12.92 : Math.pow((c+0.055)/1.055, 2.4));
 return 0.2126*lin[0] + 0.7152*lin[1] + 0.0722*lin[2];
}

function splitSentenceToWords(str) {
 const cleaned = str.replace(/[.,;:!?]/g, '');
 return cleaned.trim().split(/\s+/).filter(Boolean);
}

function shuffleArrayInPlace(arr) {
 for (let i = arr.length - 1; i > 0; i--) {
 const j = floor(random(i + 1));
 [arr[i], arr[j]] = [arr[j], arr[i]];
 }
}

function capitalizeFirst(s) {
 if (!s.length) return s;
 return s[0].toUpperCase() + s.slice(1);
}

function sanitize(str) {
 return String(str).replace(/[<>&]/g, s => ({'<':'&lt;','>':'&gt;','&':'&amp;'}[s]));
}

// ---------------- Interaction ----------------

function mousePressed(e) {
 if (e && ui && ui.elt && ui.elt.contains(e.target)) return;

 if (glitchActive) {
 let found = -1;
 for (let i = glitchRects.length - 1; i >= 0; i--) {
 const r = glitchRects[i];
 if (r.type !== 'word') continue;
 const rx = r.x, ry = r.y - r.ascent - BOX_PAD, rw = r.w, rh = r.ascent + r.descent + BOX_PAD * 2;
 if (mouseX >= rx && mouseX <= rx + rw && mouseY >= ry && mouseY <= ry + rh) { found = r.wordIndex; break; }
 }
 if (found !== -1) {
 selectedIndex = found;
 const wr = wordRects[selectedIndex];
 selBoxFillPicker.value(wr.boxFillColor ?? '#ffffff');
 selTextColorPicker.value(wr.textColor ?? textDefaultPicker.value());
 }
 return;
 }

 let found = -1;
 for (let i = wordRects.length - 1; i >= 0; i--) {
 const wr = wordRects[i];
 const rx = wr.rectX, ry = wr.y - wr.ascent - BOX_PAD, rw = wr.rectW, rh = wr.ascent + wr.descent + BOX_PAD * 2;
 if (mouseX >= rx && mouseX <= rx + rw && mouseY >= ry && mouseY <= ry + rh) { found = i; break; }
 }
 if (found !== -1) {
 selectedIndex = found;
 const wr = wordRects[selectedIndex];
 selBoxFillPicker.value(wr.boxFillColor ?? '#ffffff');
 selTextColorPicker.value(wr.textColor ?? textDefaultPicker.value());
 }
}

// ---------------- Randomizers ----------------

// #1 — colors only (uses current selected palette)
function applyRandomizer() {
 const pal = palettes[currentPaletteKey] || palettes.palette1;
 paperPicker.value(pal.paper);

 for (let wr of wordRects) {
 const choice = random(pal.boxChoices);
 wr.boxFillColor = choice;
 wr.textColor = pal.textForBox(choice);
 }
 if (currentPaletteKey === 'palette1') textDefaultPicker.value('#101010');
 else if (currentPaletteKey === 'palette2') textDefaultPicker.value('#000000');
 else textDefaultPicker.value('#101010');

 dirtyLayout = true;
 glitchLayoutDirty = true;
}

// #2 — shuffle words + Palette 1 colors
function applyWordShuffleAndColors() {
 const words = splitSentenceToWords(BASE_SENTENCE);
 shuffleArrayInPlace(words);
 const newSentence = capitalizeFirst(words.join(' ')) + '.';

 paragraph = newSentence;
 if (textArea) textArea.value(paragraph);
 wordRects = [];
 dirtyLayout = true;

 setTimeout(() => { applyRandomizerPalette1Only(); }, 0);
}

function applyRandomizerPalette1Only() {
 const pal = palettes.palette1;
 paperPicker.value(pal.paper);
 for (let wr of wordRects) {
 const choice = random(pal.boxChoices);
 wr.boxFillColor = choice;
 wr.textColor = pal.textForBox(choice);
 }
 textDefaultPicker.value('#101010');
 dirtyLayout = true;
 glitchLayoutDirty = true;
}

// #3 — Glitch (SPACERS ONLY)
function applyGlitchSpaces(chaos) {
 glitchActive = true;
 lastGlitchChaos = chaos;
 buildGlitchRects(chaos);
 glitchLayoutDirty = false;
}

// ---------------- SVG EXPORT ----------------

function buildSVGString() {
 if (glitchActive && glitchLayoutDirty) buildGlitchRects(lastGlitchChaos);

 const W = A4_W, H = A4_H;
 const paper = paperPicker.value();
 const outlineOn = outlineToggle && outlineToggle.checked();
 const strokeAttr = outlineOn ? 'stroke="#000000" stroke-width="1"' : 'stroke="none"';
 const fontSize = sizeSlider.value();
 const letterSpacing = letterSlider.value();
 const fontFamily = currentFont; // 'sans-serif' | 'serif' | 'monospace'

 const esc = (s) => String(s).replace(/[&<>"]/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[ch]));

 let svg = '';
 svg += `<?xml version="1.0" encoding="UTF-8"?>\n`;
 svg += `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" shape-rendering="crispEdges" text-rendering="geometricPrecision">\n`;

 // Background (paper)
 svg += ` <rect x="0" y="0" width="${W}" height="${H}" fill="${paper}" ${strokeAttr}/>\n`;

 const drawRect = (x, y, w, h, fill) => {
 const f = fill ? `fill="${fill}"` : `fill="none"`;
 svg += ` <rect x="${r2(x)}" y="${r2(y)}" width="${r2(w)}" height="${r2(h)}" ${f} ${strokeAttr}/>\n`;
 };

 const drawText = (str, x, y, fill) => {
 const lsAttr = letterSpacing ? ` letter-spacing="${letterSpacing}px"` : '';
 svg += ` <text x="${r2(x)}" y="${r2(y)}" fill="${fill}" font-family="${fontFamily}" font-size="${fontSize}" dominant-baseline="alphabetic"${lsAttr}>${esc(str)}</text>\n`;
 };

 if (glitchActive) {
 for (const r of glitchRects) {
 const rx = r.x;
 const ry = r.y - r.ascent - BOX_PAD;
 const rw = r.w;
 const rh = r.ascent + r.descent + BOX_PAD * 2;
 drawRect(rx, ry, rw, rh, r.boxFill || null);
 }
 for (const r of glitchRects) {
 if (r.type === 'word' && r.text) drawText(r.text, r.x, r.y, r.textFill || textDefaultPicker.value());
 }
 } else {
 for (const wr of wordRects) {
 const rx = wr.rectX;
 const ry = wr.y - wr.ascent - BOX_PAD;
 const rw = wr.rectW;
 const rh = wr.ascent + wr.descent + BOX_PAD * 2;
 drawRect(rx, ry, rw, rh, wr.boxFillColor || null);
 }
 for (const wr of wordRects) {
 const tcol = wr.textColor ? wr.textColor : textDefaultPicker.value();
 drawText(wr.word, wr.xGlyph, wr.y, tcol);
 }
 }

 svg += `</svg>\n`;
 return svg;
}

function copySVGToClipboard() {
 const svg = buildSVGString();
 if (navigator.clipboard && navigator.clipboard.writeText) {
 navigator.clipboard.writeText(svg).catch(() => fallbackCopy(svg));
 } else {
 fallbackCopy(svg);
 }
}

function fallbackCopy(text) {
 const ta = document.createElement('textarea');
 ta.value = text;
 ta.style.position = 'fixed';
 ta.style.top = '-1000px';
 document.body.appendChild(ta);
 ta.focus();
 ta.select();
 try { document.execCommand('copy'); } catch(e){}
 document.body.removeChild(ta);
}

function downloadSVGFile() {
 const svg = buildSVGString();
 const blob = new Blob([svg], { type: 'image/svg+xml;charset=utf-8' });
 const url = URL.createObjectURL(blob);
 const a = document.createElement('a');
 a.href = url;
 a.download = 'typesetter.svg';
 document.body.appendChild(a);
 a.click();
 setTimeout(() => {
 URL.revokeObjectURL(url);
 document.body.removeChild(a);
 }, 0);
}

// ---------------- small utils ----------------
function r2(n) { return Math.round(n * 100) / 100; }
function windowResized() {
 // Fixed canvas size; UI is fixed-position.
}
